#include <bits/stdc++.h>
using namespace std;

class Pizza {
public:
    string size;
    string crust;
    bool cheese;
    bool pepperoni;
    bool mushrooms;
    bool extraSauce;

    class Builder {
    public:
        string size;
        string crust;
        bool cheese = false;
        bool pepperoni = false;
        bool mushrooms = false;
        bool extraSauce = false;

        Builder(string size, string crust) : size(size), crust(crust) {}

        Builder& setCheese(bool cheese) { this->cheese = cheese; return *this; }
        Builder& setPepperoni(bool pepperoni) { this->pepperoni = pepperoni; return *this; }
        Builder& setMushrooms(bool mushrooms) { this->mushrooms = mushrooms; return *this; }
        Builder& setExtraSauce(bool extraSauce) { this->extraSauce = extraSauce; return *this; }

        Pizza build();
    };

    Pizza(const Builder& builder)
        : size(builder.size), crust(builder.crust), cheese(builder.cheese),
          pepperoni(builder.pepperoni), mushrooms(builder.mushrooms), extraSauce(builder.extraSauce) {}

    string toString() const {
        auto b = [](bool v) { return v ? "true" : "false"; };
        return "Pizza{size='" + size + "', crust='" + crust +
               "', cheese=" + b(cheese) + ", pepperoni=" + b(pepperoni) +
               ", mushrooms=" + b(mushrooms) + ", extraSauce=" + b(extraSauce) + "}";
    }
};

Pizza Pizza::Builder::build() { return Pizza(*this); }

int main() {
    Pizza pizza = Pizza::Builder("Large", "Thin").setCheese(true).setMushrooms(true).build();
    cout << pizza.toString() << endl;
    return 0;
}

