import java.util.ArrayList;
import java.util.List;

class Email {
    private final String from;
    private final List<String> to;
    private final List<String> cc;
    private final String subject;
    private final String body;
    private final boolean isHtml;
    private final String replyTo;

    private Email(Builder builder) {
        this.from = builder.from;
        this.to = List.copyOf(builder.to);
        this.cc = List.copyOf(builder.cc);
        this.subject = builder.subject;
        this.body = builder.body;
        this.isHtml = builder.isHtml;
        this.replyTo = builder.replyTo;
    }

    public void send() {
        System.out.println("─────────────────────────────");
        System.out.println("FROM    : " + from);
        System.out.println("TO      : " + String.join(", ", to));
        if (!cc.isEmpty())
            System.out.println("CC      : " + String.join(", ", cc));
        if (replyTo != null)
            System.out.println("REPLY-TO: " + replyTo);
        System.out.println("SUBJECT : " + subject);
        System.out.println("FORMAT  : " + (isHtml ? "HTML" : "Plain Text"));
        System.out.println("BODY    : " + body);
        System.out.println("─────────────────────────────");
        System.out.println("Email sent successfully!");
    }

    public static class Builder {
        // Required
        private final String from;
        private final List<String> to = new ArrayList<>();
        private final String subject;

        // Optional
        private List<String> cc = new ArrayList<>();
        private String body = "";
        private boolean isHtml = false;
        private String replyTo;

        public Builder(String from, String subject) {
            this.from = from;
            this.subject = subject;
        }

        public Builder to(String... recipients) {
            this.to.addAll(List.of(recipients));
            return this;
        }

        public Builder cc(String... recipients) {
            this.cc.addAll(List.of(recipients));
            return this;
        }

        public Builder body(String body) {
            this.body = body;
            return this;
        }

        public Builder htmlBody(String body) {
            this.body = body;
            this.isHtml = true;
            return this;
        }

        public Builder replyTo(String replyTo) {
            this.replyTo = replyTo;
            return this;
        }

        public Email build() {
            if (to.isEmpty()) {
                throw new IllegalStateException("Email must have at least one recipient.");
            }
            return new Email(this);
        }
    }
}

public class Main {
    public static void main(String[] args) {

        // Simple plain text email
        Email welcome = new Email.Builder("no-reply@app.com", "Welcome to the Platform!")
                .to("alice@example.com")
                .body("Hi Alice, thanks for signing up!")
                .build();

        // HTML email with CC and reply-to
        Email invoice = new Email.Builder("billing@app.com", "Your Invoice for October")
                .to("bob@example.com")
                .cc("accounts@app.com", "manager@app.com")
                .htmlBody("<h1>Invoice</h1><p>Total due: $149.99</p>")
                .replyTo("support@app.com")
                .build();

