        cout << "-----------------------------" << endl;
        cout << "FROM    : " << from << endl;
        cout << "TO      : " << join(to) << endl;
        if (!cc.empty())
            cout << "CC      : " << join(cc) << endl;
        if (replyTo.has_value())
            cout << "REPLY-TO: " << replyTo.value() << endl;
        cout << "SUBJECT : " << subject << endl;
        cout << "FORMAT  : " << (isHtml ? "HTML" : "Plain Text") << endl;
        cout << "BODY    : " << body << endl;
        cout << "-----------------------------" << endl;
        cout << "Email sent successfully!" << endl;
    }
};

Email Email::Builder::build() {
    if (to.empty()) {
        throw runtime_error("Email must have at least one recipient.");
    }
    return Email(*this);
}

int main() {
    // Simple plain text email
    Email welcome = Email::Builder("no-reply@app.com", "Welcome to the Platform!")
        .setTo({"alice@example.com"})
        .setBody("Hi Alice, thanks for signing up!")
        .build();

    // HTML email with CC and reply-to
    Email invoice = Email::Builder("billing@app.com", "Your Invoice for October")
        .setTo({"bob@example.com"})
        .setCc({"accounts@app.com", "manager@app.com"})
        .htmlBody("<h1>Invoice</h1><p>Total due: $149.99</p>")
        .setReplyTo("support@app.com")
        .build();

    // Team notification email
    Email alert = Email::Builder("system@app.com", "Server Down Alert")
        .setTo({"devteam@app.com", "oncall@app.com"})
        .setCc({"manager@app.com"})
        .setBody("Critical: Production server is not responding.")
        .build();

    welcome.send();
    invoice.send();
    alert.send();
    return 0;
}
